using System; // Check authoritative idle movement without depending on Unity timing.
using System.IO; // Load independently executed previous-release references.
using Outbreak.Contracts; // Inspect memory and normalize saved rules in priority comparisons.
using Outbreak.Core; // Exercise actual wandering, collision and actor opportunities.
using Outbreak.Persistence; // Verify deterministic continuation through production JSON.
public static partial class Program // Extend the existing real-code acceptance runner.
{ // Begin zombie wandering acceptance.
    private static void CheckZombieWanderCases() // Test idle chance, priority, geometry and save behavior.
    { // Begin controlled cases.
        Check("Idle zombies alternate occasional local movement with pauses", () => // A targetless zombie should shuffle without marching on every opportunity.
        { // Begin an open idle scenario with a fixed repeatable seed.
            World world = new World(new WorldMap(50, 50), 214, encounter: true); int id; world.TrySpawn(Species.Zombie, 25, 25, out id); int moves = 0, rests = 0; for (int i = 0; i < 500; i++) { ActorState before = world.ActorAt(0); world.Step(); ActorState after = world.ActorAt(0); bool moved = before.x != after.x || before.y != after.y; if (moved) { moves++; Require(world.Tick % EncounterRules.MoveInterval == id % EncounterRules.MoveInterval && Math.Abs(before.x - after.x) <= 1 && Math.Abs(before.y - after.y) <= 1, "Idle zombie teleported or moved between actor opportunities."); } else if (world.Tick % EncounterRules.MoveInterval == id % EncounterRules.MoveInterval) rests++; Require(after.targetId == 0, "Wandering invented a remembered human."); } Require(moves > 0 && moves < rests && moves + rests == 100, "Fixed-seed idle scenario did not show slow movement and pauses."); Inspect(world); // Count actual moves rather than assuming every chance succeeds.
        }); // Finish slow movement acceptance.
        Check("Idle movement respects solid corners, closed doors, bounds and full cells", () => // Chance never grants passage through geometry or crowded destinations.
        { // Begin blocked idle fixtures.
            WorldMap map = new WorldMap(3, 3); map.Set(1, 0, Terrain.DoorClosed); map.Set(0, 1, Terrain.Wall); World world = new World(map, 4, encounter: true); int id; world.TrySpawn(Species.Zombie, 0, 0, out id); Run(world, 200); Require(world.ActorAt(0).x == 0 && world.ActorAt(0).y == 0 && world.TerrainAt(1, 0) == Terrain.DoorClosed, "Idle zombie crossed a solid corner or opened a door."); Inspect(world); // The diagonal destination alone does not make the step legal.
            world = new World(new WorldMap(2, 1), 4, encounter: true); world.TrySpawn(Species.Zombie, 0, 0, out id); for (int i = 0; i < Rules.BodiesPerCell; i++) Require(world.TrySpawn(Species.Zombie, 1, 0, out id), "Full-cell fixture failed."); Run(world, 1); Require(world.ActorAt(0).x == 0, "Idle zombie entered a full cell."); for (int i = 0; i < 100; i++) { world.Step(); Inspect(world); } // Stable actor order must preserve the body limit even when the crowd starts moving.
            world = new World(new WorldMap(1, 1), 4, encounter: true); world.TrySpawn(Species.Zombie, 0, 0, out id); Run(world, 100); Require(world.ActorAt(0).x == 0 && world.ActorAt(0).y == 0, "An isolated idle zombie escaped the world boundary."); // Empty legal-step lists remain a valid resting state.
        }); // Finish collision acceptance.
        Check("Active pursuit has priority and does not consume idle random draws", () => // Adding wandering must not distract a zombie from a visible human.
        { // Begin a controlled visible encounter.
            World current = new World(new WorldMap(30, 20), 214, encounter: true, humanWarnings: false); int id; current.TrySpawn(Species.Human, 10, 10, out id); current.TrySpawn(Species.Zombie, 14, 10, out id); SaveDocument saved = current.Capture(); saved.actors[0].bravery = -3; saved.actors[0].stress = 50; current = World.Restore(saved); saved.rulesVersion = EncounterRules.RecoveryVersion; World previous = World.Restore(saved); uint initial = current.Capture().randomState; Run(current, 5); Run(previous, 5); Require(current.ActorAt(1).targetId == 1 && current.ActorAt(1).x < 14 && current.Capture().randomState == initial, "Visible pursuit wandered, stalled or consumed idle randomness."); SaveDocument oldResult = previous.Capture(); oldResult.rulesVersion = current.Capture().rulesVersion; Require(State(current) == Documents.Encode(oldResult), "Idle behavior changed an active pursuit opportunity."); // Compare all authoritative fields across the behavior boundary.
        }); // Finish priority acceptance.
        Check("A zombie investigates until expiry and then wanders without tracking the hidden human", () => // Reproduce the user's stationary-after-forgetting report.
        { // Begin a fading doorway sighting.
            World world = EncounterScenarios.ZombieWandering(); Run(world, 14); Require(world.ActorAt(1).targetId == 1 && world.ActorAt(1).x == 6 && world.ActorAt(1).y == 5, "Active blocked investigation wandered away from its door."); World resumed = Documents.ParseSave(State(world)); SaveDocument changed = world.Capture(); changed.actors[0].x = 2; changed.actors[0].y = 7; changed.actors[0].shelterX = 2; changed.actors[0].shelterY = 7; World hiddenElsewhere = World.Restore(changed); world.Step(); resumed.Step(); hiddenElsewhere.Step(); Require(world.ActorAt(1).targetId == 0 && world.ActorAt(1).searchUntilTick == 0 && world.ActorAt(1).x == 6, "Memory did not expire exactly between movement opportunities."); bool moved = false; for (int i = 0; i < 100; i++) { ActorState before = world.ActorAt(1); world.Step(); resumed.Step(); hiddenElsewhere.Step(); ActorState after = world.ActorAt(1); moved |= before.x != after.x || before.y != after.y; Require(State(world) == State(resumed), "Post-memory wandering changed after reload."); Require(Documents.Encode(after) == Documents.Encode(hiddenElsewhere.ActorAt(1)) && world.Capture().randomState == hiddenElsewhere.Capture().randomState, "Idle zombie learned the hidden human's changed position."); Require(after.targetId == 0 && world.TerrainAt(5, 5) == Terrain.DoorClosed && world.ActorAt(0).turnAtTick == 0, "Wandering refreshed a hidden target or bypassed the closed room."); } Require(moved, "Zombie remained permanently stationary after forgetting."); Inspect(world); // Preserve both exact expiry and non-omniscient movement afterward.
        }); // Finish memory transition acceptance.
        Check("Wandering pauses exactly and resumes from the saved random state", () => // Frame timing must not change the idle movement sequence.
        { // Begin deterministic idle continuation.
            World world = new World(new WorldMap(30, 30), 42, encounter: true); int id; for (int i = 0; i < 12; i++) world.TrySpawn(Species.Zombie, 10 + i % 4, 10 + i / 4, out id); Run(world, 137); string paused = State(world); TickClock clock = new TickClock(); clock.Advance(500, world.Step); Require(State(world) == paused, "Paused idle zombies moved or consumed random draws."); World resumed = Documents.ParseSave(paused); for (int i = 0; i < 100; i++) { world.Step(); resumed.Step(); Require(State(world) == State(resumed), "Saved idle random continuation drifted."); } Inspect(world); // Compare complete state throughout a resumed multi-zombie run.
        }); // Finish persistence acceptance.
        Check("Prototype-eight saves retain their independent stationary-idle continuation", () => // Enable wandering only in new scenarios or after an explicit update.
        { // Begin previous-release compatibility.
            string folder = Path.Combine(AppContext.BaseDirectory, "Fixtures"); World world = Documents.ParseSave(File.ReadAllText(Path.Combine(folder, "encounter-v8-input.json"))); Require(world.ShelterRecovery && !world.ZombieWandering, "Previous recovery run silently gained wandering."); Run(world, 200); Require(State(world) == State(Documents.ParseSave(File.ReadAllText(Path.Combine(folder, "encounter-v8-expected.json")))), "Prior recovery continuation changed."); // Reference source was independently executed at commit 051d500.
        }); // Finish compatibility acceptance.
    } // Finish idle movement cases.
} // Finish runner integration.
